"""Authored two-way school-adjacent road and turn envelope; designation unreviewed."""
import math
import xml.etree.ElementTree as ET

ZONE={'x_min_m':-20,'x_max_m':20,'y_min_m':-8,'y_max_m':8}
TURN={'center_x_m':-12,'center_y_m':0,'radius_m':5.5,'first_frame':100,'last_frame':220}


def open_drive():
    root=ET.Element('OpenDRIVE')
    ET.SubElement(root,'header',revMajor='1',revMinor='4',name='C263073 school zone draft',version='1',date='2026-11-23',north='30',south='-30',east='60',west='-60',vendor='worker')
    road=ET.SubElement(root,'road',id='1',name='school-adjacent two-way road',length='120',junction='-1')
    ET.SubElement(road,'link');geometry=ET.SubElement(ET.SubElement(road,'planView'),'geometry',s='0',x='-60',y='0',hdg='0',length='120')
    ET.SubElement(geometry,'line');ET.SubElement(ET.SubElement(road,'elevationProfile'),'elevation',s='0',a='0',b='0',c='0',d='0')
    section=ET.SubElement(ET.SubElement(road,'lanes'),'laneSection',s='0')
    left=ET.SubElement(section,'left');plus=ET.SubElement(left,'lane',id='1',type='driving',level='false')
    ET.SubElement(plus,'width',sOffset='0',a='6',b='0',c='0',d='0')
    center=ET.SubElement(section,'center');ET.SubElement(center,'lane',id='0',type='none',level='false')
    right=ET.SubElement(section,'right');minus=ET.SubElement(right,'lane',id='-1',type='driving',level='false')
    ET.SubElement(minus,'width',sOffset='0',a='6',b='0',c='0',d='0')
    ET.SubElement(road,'objects');ET.SubElement(road,'signals')
    return ET.tostring(root,encoding='unicode')


def planned_pose(index,turn):
    if not turn:
        return (-25+min(index,250)*.2,-5.5,0)
    if index<100:return (-25+index*.13,-5.5,0)
    if index<=220:
        angle=-math.pi/2+math.pi*(index-100)/120
        return (TURN['center_x_m']+TURN['radius_m']*math.cos(angle),
            TURN['radius_m']*math.sin(angle),
            90+math.degrees(angle))
    return (-12-min(index-220,160)*.2,5.5,180)


def check():
    root=ET.fromstring(open_drive());lanes=root.findall('road/lanes/laneSection/left/lane')+root.findall('road/lanes/laneSection/right/lane')
    if [x.get('id') for x in lanes]!=['1','-1']:raise ValueError('Two-way turning envelope missing')
    a=planned_pose(100,True);b=planned_pose(220,True)
    if abs(a[1]+5.5)>1e-6 or abs(b[1]-5.5)>1e-6 or abs(b[2]-180)>1e-6:
        raise ValueError('Authored reversal differs')
    return {'passed':True,'zone':ZONE,'turn':TURN,'road_lane_ids':[1,-1],
        'zone_designation_reviewed':False,'child_age_or_presence_rule_adopted':False}

"""Engineering path follower for a physically simulated school-zone reversal."""
import math

from layout import planned_pose


def command(index, turn, location_xy, yaw_deg, speed_mps):
    """Return steering/throttle/brake; these are motion controls, not legal tests."""
    if index < 0 or index >= 600:
        raise ValueError('Frame outside the 30-second capture')
    target_index = min(index + 12, 599)
    target_x, target_y, _ = planned_pose(target_index, turn)
    dx, dy = target_x - location_xy[0], target_y - location_xy[1]
    distance = math.hypot(dx, dy)
    if not all(math.isfinite(v) for v in (target_x, target_y, yaw_deg, speed_mps, distance)):
        raise ValueError('Nonfinite physical motion input')
    if speed_mps < 0 or speed_mps > 80:
        raise ValueError('Invalid physical speed')
    terminal = index >= (390 if turn else 270) and distance < 2.0
    if terminal:
        return {'steer': 0.0, 'throttle': 0.0, 'brake': 0.7,
                'target_xy_m': [target_x, target_y], 'target_speed_mps': 0.0}
    bearing = math.degrees(math.atan2(dy, dx))
    error = ((bearing - yaw_deg + 180) % 360) - 180
    steer = max(-1.0, min(1.0, error / 35.0))
    target_speed = 2.6 if turn and 95 <= index <= 240 else 3.0
    throttle = max(0.0, min(0.55, 0.25 + 0.2 * (target_speed - speed_mps)))
    brake = max(0.0, min(0.5, 0.25 * (speed_mps - target_speed)))
    return {'steer': steer, 'throttle': throttle, 'brake': brake,
            'target_xy_m': [target_x, target_y], 'target_speed_mps': target_speed}

"""Original Native school-zone U-turn draft; --check is CARLA-free."""
import argparse
import json
import os
from pathlib import Path
import queue
import subprocess

from layout import ZONE,TURN,check as layout_check,open_drive,planned_pose
from drive import command
from review_context import attach_original_review
from branch_cases import CASES,check_review

FRAMES=600
CAMERAS=(('overview',1920,1080,-12,-18,25,-65),('approach',1280,720,-25,-12,8,-30),
    ('reference_corner',1280,720,5,13,12,-45),('driver_reference',1280,720,.5,0,1.6,0))


def check():
    cfg=json.loads(Path('config.json').read_text())
    if cfg['cell_id']!='C263073' or cfg['law_id']!='NRS-484B-363-3' or cfg['case_suffix'] not in CASES:
        raise ValueError('Exact assignment differs')
    if cfg.get('branch_context') != CASES[cfg['case_suffix']]:
        raise ValueError('Exact selected branch context differs')
    if cfg.get('vehicle_blueprint') not in ('vehicle.tesla.model3','vehicle.mini.cooper_s'):
        raise ValueError('Unexpected original vehicle blueprint')
    if cfg['duration_s']!=30 or cfg['rate_hz']!=20 or len(CAMERAS)!=4 or CAMERAS[0][1:3]!=(1920,1080):
        raise ValueError('Capture policy differs')
    if [(item.get('name'),item.get('width'),item.get('height')) for item in cfg.get('cameras',[])] != [
        (name,width,height) for name,width,height,*_ in CAMERAS]:
        raise ValueError('Four-camera config differs from original Native construction')
    return {'passed':True,'geometry':layout_check(),'frame_count':FRAMES,
        'kinematic_path_only':False,'native_imported':False,'physical_acceptance_claimed':False}


def actor_row(actor):
    transform=actor.get_transform()
    return {'actor_id':actor.id,'blueprint_id':actor.type_id,
        'center_xy_m':[transform.location.x,transform.location.y],
        'heading_deg':transform.rotation.yaw,
        'body_xy_m':[[p.x,p.y] for p in actor.bounding_box.get_world_vertices(transform)]}


def execute(output,host,port,review_source_dir):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap,seal_capture
    from worker_exchange.world_restore import snapshot,restore
    cfg=json.loads(Path('config.json').read_text());check();output=Path(output).resolve()
    if not output.is_dir() or not (output/'construction.json').is_file() or not (output/'config.json').is_file():
        raise ValueError('Native output must be a fresh materialized exact-case directory')
    if (output/'native-motion.jsonl').exists() or (output/'capture-seal.json').exists():
        raise ValueError('Original Native acquisition already exists')
    review_source_dir=Path(review_source_dir).resolve()
    from review_context import verified_sources
    try:
        review_packet=json.loads((review_source_dir/'review.json').read_text())
        verified_sources(review_source_dir,review_packet)
        check_review(review_packet['independent_review'],cfg['case_suffix'])
    except BaseException as exc:
        (output/'native-run-status.json').write_text(json.dumps({
            'errors':[{'pre_capture_source_error':str(exc)}],'frames':0},indent=2)+'\n')
        raise
    try:
        client=carla.Client(host,port);client.set_timeout(180)
        old=client.get_world();saved=snapshot(client)
        if old.get_settings().synchronous_mode or any(a.type_id.startswith(('vehicle.','walker.','sensor.','controller.')) for a in old.get_actors()):
            raise RuntimeError('Exclusive idle asynchronous Native world required')
    except BaseException as exc:
        (output/'native-run-status.json').write_text(json.dumps({
            'errors':[{'native_preflight_error':str(exc)}],'frames':0},indent=2)+'\n')
        raise
    owned=[];encoders={};queues={};changed=False;pipeline_capture=None
    frames=[];encoder_exit_codes={};errors=[];restoration={'restored':False}
    try:
        world=client.generate_opendrive_world(open_drive(),carla.OpendriveGenerationParameters(
            vertex_distance=.5,max_road_length=50,wall_height=0,additional_width=0,
            smooth_junctions=False,enable_mesh_visibility=True,enable_pedestrian_navigation=False))
        changed=True;settings=world.get_settings();settings.synchronous_mode=True
        settings.fixed_delta_seconds=.05;settings.substepping=True
        settings.max_substep_delta_time=.01;settings.max_substeps=10;world.apply_settings(settings)
        mapping=world.get_map()
        for y,lane in ((-5.5,-1),(5.5,1)):
            waypoint=mapping.get_waypoint(carla.Location(x=-12,y=y,z=1),project_to_road=True,lane_type=carla.LaneType.Driving)
            if waypoint is None or waypoint.road_id!=1 or waypoint.lane_id!=lane:
                raise RuntimeError('Native two-way road readback failed')
        # Diagnostic zone outline does not establish legal designation or sign/beacon activity.
        for x in (-20,20):
            world.debug.draw_line(carla.Location(x=x,y=-8,z=.05),carla.Location(x=x,y=8,z=.05),
                thickness=.08,color=carla.Color(255,255,0),life_time=35,persistent_lines=False)
        bp=world.get_blueprint_library().find(cfg['vehicle_blueprint'])
        ego=world.try_spawn_actor(bp,carla.Transform(carla.Location(x=-25,y=-5.5,z=1.2),carla.Rotation(yaw=0)))
        if ego is None:raise RuntimeError('Original vehicle spawn failed')
        ego.set_simulate_physics(True);owned.append(ego)
        (output/'acquisition-provenance.json').write_text(json.dumps({
            'provenance_kind':'native','diagnostic_fixture':False,
            'physical_acceptance_claimed':False},indent=2)+'\n')
        pipeline_capture=PipelineCapture(client,ego,output,cfg['case_id'],
            visibility=False,required_observations=cfg.get('required_atoms',[]))
        walker=None
        if cfg['branch_context']['child_actor']:
            walker_bp=next((x for x in world.get_blueprint_library().filter('walker.pedestrian.*')),None)
            if walker_bp is None:raise RuntimeError('Original pedestrian blueprint missing')
            walker=world.try_spawn_actor(walker_bp,carla.Transform(carla.Location(x=4,y=7.5,z=1.2)))
            if walker is None:raise RuntimeError('Original pedestrian spawn failed')
            owned.append(walker)
        for name,width,height,x,y,z,pitch in CAMERAS:
            cbp=world.get_blueprint_library().find('sensor.camera.rgb')
            for key,value in (('image_size_x',width),('image_size_y',height),('fov',85),('sensor_tick',.05)):
                cbp.set_attribute(key,str(value))
            camera_pose=carla.Transform(carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch))
            sensor=world.spawn_actor(cbp,camera_pose,attach_to=ego if name=='driver_reference' else None)
            owned.append(sensor);received=queue.Queue();sensor.listen(received.put);queues[name]=received
            encoders[name]=subprocess.Popen(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n',
                '-f','rawvideo','-pix_fmt','bgra','-s',f'{width}x{height}','-r','20','-i','-',
                '-frames:v',str(FRAMES),'-c:v','ffv1',str(output/(name+'.mkv'))],stdin=subprocess.PIPE,stderr=subprocess.PIPE)
        with (output/'native-motion.jsonl').open('x') as motion,FrameMap(output/'video_frames.jsonl') as frame_map:
            for index in range(FRAMES):
                transform=ego.get_transform();velocity=ego.get_velocity()
                control=command(index,cfg['branch_context']['turn'],
                    (transform.location.x,transform.location.y),transform.rotation.yaw,
                    (velocity.x**2+velocity.y**2)**.5)
                ego.apply_control(carla.VehicleControl(steer=control['steer'],
                    throttle=control['throttle'],brake=control['brake']))
                native=world.tick()
                pipeline_capture.capture(native,index/20)
                motion.write(json.dumps({'frame':native,'native_frame':native,'video_frame':index,'time_s':index/20,
                    'source_kind':'original_native','ego':actor_row(ego),
                    'other_person':actor_row(walker) if walker is not None else None,'control':control,
                    'kinematic_path_only':False},allow_nan=False)+'\n')
                camera_frames={}
                for name,*_ in CAMERAS:
                    image=queues[name].get(timeout=30)
                    while image.frame<native:image=queues[name].get(timeout=30)
                    if image.frame!=native:raise RuntimeError('Original four-camera join differs')
                    encoders[name].stdin.write(image.raw_data);camera_frames[name]=image.frame
                frames.append(frame_map.append(native,index/20,camera_native_frames=camera_frames))
        pipeline_capture.close(confirmed=True);pipeline_capture=None
        for name,process in encoders.items():
            process.stdin.close();error=process.stderr.read();code=process.wait(timeout=180)
            encoder_exit_codes[name]=code
            if code or not (output/(name+'.mkv')).is_file():
                raise RuntimeError('Original FFV1 encoding failed: '+name+error.decode()[-400:])
        (output/'frame-map.json').write_text(json.dumps(frames)+'\n')
        (output/'road.xodr').write_text(open_drive())
        independent_review=attach_original_review(output,review_source_dir)
        (output/'school-context.json').write_text(json.dumps({'source_kind':'original_native',
            'cell_id':'C263073','zone':ZONE,'turn':TURN,'zone_designation_reviewed':False,
            'school_adjacency_reviewed':False,'highway_status_reviewed':False,
            'child_identity_and_presence_reviewed':False,'session_operation_civil_time_reviewed':False,
            'class_hours_reviewed':False,'beacon_and_sign_state_reviewed':False,
            'all_five_exceptions_reviewed':False,'partial_zone_maneuver_treatment_reviewed':False,
            'path_is_kinematic':False,'independent_review':independent_review},indent=2)+'\n')
    except BaseException as exc:
        errors.append({'type':type(exc).__name__,'message':str(exc)})
        raise
    finally:
        if pipeline_capture is not None:
            try:pipeline_capture.close(confirmed=False)
            except BaseException as exc:errors.append({'capture_close_error':str(exc)})
        for process in encoders.values():
            if process.poll() is None:process.kill();process.wait()
        for actor in reversed(owned):
            try:
                if hasattr(actor,'stop'):actor.stop()
                actor.destroy()
            except Exception:pass
        if changed:
            try:restoration=restore(client,saved)
            except BaseException as exc:errors.append({'restore_error':str(exc)})
        (output/'native-attempt-status.json').write_text(json.dumps({
            'frames':len(frames),'errors':errors,'physical_completion':None,
            'legal_verdict':None},indent=2)+'\n')
        if errors:
            (output/'native-run-status.json').write_text(json.dumps({
                'errors':errors,'frames':len(frames)},indent=2)+'\n')
    if errors:raise RuntimeError('Native capture failed: '+str(errors))
    try:
        seal_capture(output,frames=len(frames),restoration=restoration,errors=[],
            encoder_exit_codes=encoder_exit_codes,
            context={'school_zone_source_review_bound':True,'physical_completion':None})
    except BaseException as exc:
        (output/'native-run-status.json').write_text(json.dumps({
            'errors':[{'capture_seal_error':str(exc)}],'frames':len(frames)},indent=2)+'\n')
        raise
    return {'frames':len(frames),'camera_names':list(queues),'path_is_kinematic':False,
        'zone_designation_unverified':True,'physical_acceptance_claimed':False}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir',type=Path);parser.add_argument('--host',default='localhost')
    parser.add_argument('--port',type=int,default=2000)
    parser.add_argument('--review-source-dir',type=Path);args=parser.parse_args()
    if args.check:print(json.dumps(check()))
    else:
        review_dir=args.review_source_dir or os.environ.get('C263073_REVIEW_SOURCE_DIR')
        if args.output_dir is None or review_dir is None:
            parser.error('Materialized Native output and C263073_REVIEW_SOURCE_DIR required')
        print(json.dumps(execute(args.output_dir,args.host,args.port,review_dir)))

"""Measure original school-zone trajectory and person position without legal thresholds."""
import argparse
import hashlib
import json
import math
from pathlib import Path
from review_context import verified_sources
from branch_cases import CASES,check_review

FRAMES=600
CAMERAS=('overview','approach','reference_corner','driver_reference')


def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(path):
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    data=[json.loads(line) for line in path.read_text().splitlines()]
    if len(data)!=FRAMES:raise ValueError('Original source must contain 600 frames')
    return data


def xy(actor):
    value=actor.get('center_xy_m')
    if not isinstance(value,list) or len(value)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in value):
        raise ValueError('Original actor position missing')
    return value


def inside(point,zone):
    return zone['x_min_m']<=point[0]<=zone['x_max_m'] and zone['y_min_m']<=point[1]<=zone['y_max_m']


def measure(attempt):
    attempt=Path(attempt);context_path=attempt/'school-context.json'
    motion_path=attempt/'native-motion.jsonl';frames_path=attempt/'video_frames.jsonl'
    for path in (context_path,motion_path,frames_path):
        if not path.is_file():raise ValueError('Missing required source: '+path.name)
    context=json.loads(context_path.read_text());zone=context.get('zone')
    if context.get('source_kind')!='original_native':
        raise ValueError('Original school-zone context missing')
    if context.get('path_is_kinematic') is not False:
        raise ValueError('Physically driven original path required')
    review=verified_sources(attempt,context)
    config=json.loads((attempt/'config.json').read_text())
    branch=check_review(review,config['case_suffix'])
    if not isinstance(zone,dict) or any(type(zone.get(k)) not in (int,float) for k in ('x_min_m','x_max_m','y_min_m','y_max_m')):
        raise ValueError('Original zone extent missing')
    motions,frames=rows(motion_path),rows(frames_path)
    previous=-1;headings=[];inside_frames=[];person_inside=[];positions=[]
    for index,(row,frame) in enumerate(zip(motions,frames)):
        native=row.get('native_frame')
        if type(native) is not int or native<=previous or frame.get('native_frame')!=native:
            raise ValueError('Original Native frame join differs')
        previous=native
        if row.get('video_frame')!=index or frame.get('video_frame')!=index or abs(row.get('time_s',-1)-index/20)>1e-6 or abs(frame.get('time_s',-1)-index/20)>1e-6:
            raise ValueError('Original video frame/time join differs')
        if frame.get('camera_native_frames')!={name:native for name in CAMERAS}:
            raise ValueError('Original four-camera join differs')
        ego=row.get('ego',{});person=row.get('other_person')
        control=row.get('control')
        if row.get('kinematic_path_only') is not False or not isinstance(control,dict) or any(
            type(control.get(key)) not in (int,float) or not math.isfinite(control[key])
            for key in ('steer','throttle','brake')):
            raise ValueError('Original physical vehicle control missing')
        point=xy(ego)
        if branch['child_actor'] != (person is not None):
            raise ValueError('Original child-actor presence differs from selected branch')
        person_point=xy(person) if person is not None else None
        heading=ego.get('heading_deg')
        if type(heading) not in (int,float) or not math.isfinite(heading):
            raise ValueError('Original heading missing')
        headings.append(heading);positions.append(point)
        if inside(point,zone):inside_frames.append(index)
        if person_point is not None and inside(person_point,zone):person_inside.append(index)
    for name in CAMERAS:
        if not (attempt/(name+'.mkv')).is_file():raise ValueError('Missing required source: '+name+'.mkv')
    cumulative=sum(abs(((b-a+180)%360)-180) for a,b in zip(headings,headings[1:]))
    return {'format':'c263073-school-zone-turn-raw-motion-v1','frame_count':FRAMES,
        'rate_hz':20,'first_ego_zone_frame':inside_frames[0] if inside_frames else None,
        'ego_zone_frame_count':len(inside_frames),'other_person_zone_frame_count':len(person_inside),
        'initial_heading_deg':headings[0],'final_heading_deg':headings[-1],
        'cumulative_absolute_heading_change_deg':cumulative,
        'path_is_kinematic':context.get('path_is_kinematic') is True,
        'child_age_or_presence_radius_adopted':False,'legal_heading_threshold_adopted':False,
        'session_operation_civil_time_reviewed':context.get('session_operation_civil_time_reviewed') is True,
        'beacon_and_sign_state_reviewed':context.get('beacon_and_sign_state_reviewed') is True,
        'all_five_exceptions_reviewed':context.get('all_five_exceptions_reviewed') is True,
        'independent_source_review':review,
        'u_turn_legal_verdict':'unresolved','physical_acceptance_claimed':False,
        'source_sha256':{p.name:sha(p) for p in (context_path,motion_path,frames_path)},
        'camera_video_sha256':{name:sha(attempt/(name+'.mkv')) for name in CAMERAS}}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    if args.output.exists():raise ValueError('Use fresh measurement output')
    value=measure(args.attempt);args.output.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
    print(json.dumps({'cumulative_absolute_heading_change_deg':value['cumulative_absolute_heading_change_deg'],
        'u_turn_legal_verdict':'unresolved'}))


if __name__=='__main__':main()

"""Check provenance of independent school-zone facts, without legal conclusions."""
import hashlib
import json
import shutil
from pathlib import Path


REQUIRED = (
    'zone_designation', 'zone_boundaries', 'school_adjacency', 'highway_status',
    'driver_identity', 'driver_control', 'vehicle_classification',
    'child_identity', 'child_location', 'school_session', 'school_operation',
    'class_hours', 'civil_time', 'beacon_configuration', 'beacon_lights',
    'zone_sign',
)
EXCEPTIONS = ('a_no_children', 'b_not_in_session', 'c_operation_interval',
              'd_operational_beacon_class_hours', 'e_no_operational_beacon_sign')
EXCEPTION_TOPICS = {
    'a_no_children': {'child_identity', 'child_location'},
    'b_not_in_session': {'school_session', 'civil_time'},
    'c_operation_interval': {'school_operation', 'civil_time'},
    'd_operational_beacon_class_hours': {'beacon_configuration', 'beacon_lights', 'class_hours', 'civil_time'},
    'e_no_operational_beacon_sign': {'beacon_configuration', 'zone_sign', 'civil_time'},
}


def verified_sources(attempt, context):
    """Bind supplied review records to bytes; no worker record proves a statute."""
    attempt = Path(attempt).resolve()
    review = context.get('independent_review')
    if not isinstance(review, dict) or review.get('format') != 'c263073-source-review-v1':
        raise ValueError('Independent school-zone source review missing')
    records = review.get('records')
    if not isinstance(records, dict) or set(records) != set(REQUIRED):
        raise ValueError('Independent source record inventory incomplete')
    bound = {}
    for topic in REQUIRED:
        record = records[topic]
        if not isinstance(record, dict) or record.get('topic') != topic:
            raise ValueError('Independent source topic differs: ' + topic)
        relative = record.get('path')
        digest = record.get('sha256')
        if not isinstance(relative, str) or not relative or not isinstance(digest, str) or len(digest) != 64:
            raise ValueError('Independent source reference missing: ' + topic)
        path = (attempt / relative).resolve()
        if not path.is_relative_to(attempt) or not path.is_file():
            raise ValueError('Independent source file missing: ' + topic)
        if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ValueError('Independent source hash differs: ' + topic)
        if not isinstance(record.get('reviewer'), str) or not record['reviewer'].strip():
            raise ValueError('Independent source reviewer missing: ' + topic)
        if not isinstance(record.get('observation'), str) or not record['observation'].strip():
